const axios = require('axios');
const cheerio = require('cheerio');

// URL базовой страницы Google Images
const BASE_URL = 'https://www.google.com/search?q=';
const IMG_TBS = '&tbm=isch';

async function getGoogleImages(query) {
  try {
    const encodedQuery = encodeURIComponent(query);
    const url = `${BASE_URL}${encodedQuery}${IMG_TBS}`;

    const response = await axios.get(url);
    const $ = cheerio.load(response.data);

    const images = [];
    $('#islrg > div > a > img').each((index, element) => {
      const imageUrl = $(element).attr('src');
      if (imageUrl && imageUrl.startsWith('http')) {
        images.push(imageUrl);
      }
    });

    return images;
  } catch (error) {
    console.error('Error fetching images:', error);
    return [];
  }
}

// Функция для вывода результатов
function printImages(images) {
  console.log('Found images:');
  images.forEach((url, index) => {
    console.log(`${index + 1}: ${url}`);
  });
}

// Запуск функции поиска изображений
(async () => {
  const query = 'бей беги';
  const images = await getGoogleImages(query);
  printImages(images);
})();
```

