import org.springframework.scheduling.config.ScheduledTaskRegistrar;
import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;
import org.springframework.scheduling.support.CronTrigger;
import org.springframework.context.annotation.Configuration;
import org.springframework.schedulingConfigurer;

@Configuration
public class SchedulingConfig implements SchedulingConfigurer {

    @Override
    public void configureTasks(ScheduledTaskRegistrar taskRegistrar) {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
        scheduler.setPoolSize(5); // Set the pool size as needed
        scheduler.initialize();

        taskRegistrar.setScheduler(scheduler);

        // Define and schedule a task
        taskRegistrar.addCronTask(() -> System.out.println("Task executed"), "0/10 * * * * ?");
    }

    @Override
    public void configureScheduler(ApplicationContext applicationContext, TaskSchedulerBuilder<?> builder) {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
        scheduler.setPoolSize(5); // Set the pool size as needed
        scheduler.initialize();

        builder.scheduler(scheduler);
    }
}
```

In this example, `configureTasks` sets up and schedules a task using the configured scheduler. The `configureScheduler` method configures the scheduler itself. `configureTasks` is called after `configureScheduler`, ensuring that the scheduler is fully set up before tasks are scheduled.

