```javascript
const request = require('request');
const cheerio = require('cheerio');
const queryString = require('querystring');

const baseURL = 'http://images.google.com/search?';
const imageFileExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.svg'];

function gis(query, done) {
  const url = `${baseURL}${queryString.stringify({ tbm: 'isch', q: query })}`;

  const reqOpts = {
    url: url,
    headers: {
      'User-Agent': 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_11_6) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/61.0.3163.100 Safari/537.36'
    }
  };

  request(reqOpts, parseGISResponse);

  function parseGISResponse(error, response, body) {
    if (error) {
      return done(error);
    }

    const $ = cheerio.load(body);
    const scripts = $('script');
    let imageUrls = [];

    scripts.each((index, element) => {
      const content = $(element).children().first().text();
      if (content && containsAnyImageFileExtension(content)) {
        const matches = content.match(/["'](\S+\.jpe?g|\.png|\.gif|\.bmp|\.svg)["']/);
        if (matches) {
          imageUrls.push(matches[1]);
        }
      }
    });

    if (imageUrls.length > 0) {
      done(null, imageUrls[0]);
    } else {
      done(new Error('No images found'));
    }
  }

  function containsAnyImageFileExtension(s) {
    return imageFileExtensions.some(ext => s.includes(ext));
  }
}

// Пример использования
gis('бей беги', (err, imageUrl) => {
  if (err) {
    console.error(err);
  } else {
    console.log('Первая найденная ссылка:', imageUrl);
  }
});
```

